import pytest
from candidate import parse_music


class TestParseMusicNormalCases:
    def test_single_whole_note(self):
        assert parse_music('o') == [4]

    def test_single_half_note(self):
        assert parse_music('o|') == [2]

    def test_single_quarter_note(self):
        assert parse_music('.|') == [1]

    def test_multiple_whole_notes(self):
        assert parse_music('o o o') == [4, 4, 4]

    def test_multiple_half_notes(self):
        assert parse_music('o| o| o|') == [2, 2, 2]

    def test_multiple_quarter_notes(self):
        assert parse_music('.| .| .|') == [1, 1, 1]

    def test_mixed_notes_example(self):
        assert parse_music('o o| .| o| o| .| .| .| .| o o') == [4, 2, 1, 2, 2, 1, 1, 1, 1, 4, 4]

    def test_two_different_notes(self):
        assert parse_music('o o|') == [4, 2]

    def test_alternating_notes(self):
        assert parse_music('o o| .| o .| o|') == [4, 2, 1, 4, 1, 2]


class TestParseMusicEdgeCases:
    def test_empty_string_returns_empty_list(self):
        assert parse_music('') == []

    def test_single_space_returns_empty_list(self):
        assert parse_music(' ') == []

    def test_multiple_spaces_returns_empty_list(self):
        assert parse_music('   ') == []

    def test_leading_and_trailing_spaces(self):
        assert parse_music(' o o| ') == [4, 2]

    def test_multiple_consecutive_spaces(self):
        assert parse_music('o  o|  .|') == [4, 2, 1]

    def test_single_note_no_spaces(self):
        assert parse_music('o') == [4]

    def test_two_notes_with_single_space(self):
        assert parse_music('o o|') == [4, 2]


class TestParseMusicErrorCases:
    def test_none_input_raises_attribute_error(self):
        with pytest.raises(AttributeError):
            parse_music(None)

    def test_integer_input_raises_attribute_error(self):
        with pytest.raises(AttributeError):
            parse_music(123)

    def test_list_input_raises_attribute_error(self):
        with pytest.raises(AttributeError):
            parse_music(['o', 'o|'])

    def test_unknown_token_raises_key_error(self):
        with pytest.raises(KeyError):
            parse_music('x')

    def test_mixed_unknown_token_raises_key_error(self):
        with pytest.raises(KeyError):
            parse_music('o abc .|')

    def test_empty_token_in_middle_is_filtered(self):
        assert parse_music('o  .|') == [4, 1]

    def test_all_spaces_between_notes(self):
        assert parse_music('o    o|') == [4, 2]


class TestParseMusicReturnType:
    def test_returns_list(self):
        result = parse_music('o o| .|')
        assert isinstance(result, list)

    def test_returns_list_of_integers(self):
        result = parse_music('o o| .|')
        assert all(isinstance(x, int) for x in result)

    def test_returns_empty_list_for_no_notes(self):
        result = parse_music('')
        assert isinstance(result, list)
        assert len(result) == 0


class TestParseMusicIndependence:
    def test_order_preserved(self):
        assert parse_music('.| o o| .|') == [1, 4, 2, 1]

    def test_repeated_calls_same_result(self):
        assert parse_music('o o| .|') == parse_music('o o| .|')

    def test_does_not_mutate_input(self):
        s = 'o o| .|'
        parse_music(s)
        assert s == 'o o| .|'
